

SELECT (SELECT id FROM lessons WHERE title = 'Oxford 3000'), v.id, v.id
FROM vocab v WHERE v.term IN ('a','abandon','abandoned','ability','able','about','above','abroad','absence','absent','absolute','absolutely','absorb','abuse','academic','accent','accept','acceptable','access','accident','accidental','accidentally','accommodation','accompany','according to','account','accurate','accurately','accuse','achieve','achievement','acid','acknowledge','acquire','across','act','action','active','actively','activity','actor','actress','actual','actually','adapt','add','addition','additional','address','adequate','adequately','adjust','admiration','admire','admit','adopt','adult','advance','advanced','advantage','adventure','advertise','advertisement','advertising','advice','advise','affair','affect','affection','afford','afraid','after','afternoon','afterwards','again','against','age','aged','agency','agent','aggressive','ago','agree','agreement','ahead','aid','aim','air','aircraft','airport','alarm','alarmed','alarming','alcohol','alcoholic','alive','all','all right','allied','allow')
ON CONFLICT(lesson_id, vocab_id) DO NOTHING;
